"""Apply verified PaymentSucceeded events to the existing Supabase Pagos table."""
import logging
from datetime import datetime

from src.domain.entities.payment import PaymentStatus

logger = logging.getLogger(__name__)


class SupabasePaymentProjection:
    target = "supabase.Pagos"

    def __init__(self, store, client):
        self.store, self.client = store, client

    async def apply(self, event):
        # Queue credentials alone do not authorize asserting that Stripe approved a payment.
        # Require the durable event generated by our verified webhook/reconciliation.
        stored = self.store.stored_success(event["event_id"])
        if stored is None or stored.payload != {key: event[key] for key in stored.payload}:
            raise ValueError("Success event does not match the verified local outbox")
        payment = self.store.get(event["payment_id"])
        expected = {
            "payment_id": event["payment_id"], "order_id": event["order_id"],
            "user_id": event["user_id"], "event_id": event["event_id"],
            "provider_session_id": event["provider_session_id"],
            "amount_minor": event["amount_minor"], "currency": event["currency"],
            "status": "succeeded", "livemode": False,
        }
        if payment is None or payment.status != PaymentStatus.SUCCEEDED or (
            payment.order_id, payment.user_id, payment.provider_session_id, payment.amount_minor, payment.currency
        ) != (
            event["order_id"], event["user_id"], event["provider_session_id"], event["amount_minor"], event["currency"]
        ):
            raise ValueError("Payment is not a matching verified success")
        payload = expected | {"confirmed_at": stored.occurred_at}
        # Postgres UNIQUE constraints + ON CONFLICT DO NOTHING make repeated delivery safe.
        result = await self.client.table("Pagos").upsert(
            payload, on_conflict="payment_id", ignore_duplicates=True,
        ).execute()
        saved = await self.client.table("Pagos").select("*").eq("payment_id", payment.id).execute()
        if not saved.data:
            raise RuntimeError("Supabase did not confirm payment persistence")
        row = saved.data[0]
        if any(row.get(key) != value for key, value in expected.items()):
            raise ValueError("Existing Pagos row conflicts with the verified event")
        confirmed_at = datetime.fromisoformat(str(row["confirmed_at"]))
        source_time = datetime.fromisoformat(stored.occurred_at)
        if confirmed_at != source_time:
            raise ValueError("Existing Pagos row has a different confirmation timestamp")
        # A crash before this receipt causes another delivery, not another DB row.
        self.store.apply_projection(event)
        self.store.record_projection_receipt(event["event_id"], self.target)
        logger.info("payment_projection_%s target=%s event_id=%s payment_id=%s order_id=%s",
                    "applied" if result.data else "duplicate", self.target,
                    event["event_id"], payment.id, payment.order_id)
